 "path": "/amazon/prime/plans",
 "method": "GET",
 "description": "Show information about prime plans available. Delivery fee is waived for prime members.",
 "parameters": [],
 "response_schemas": {
  "success": {
   "monthly": 1,
   "yearly": 1
  },
  "failure": {
   "message": "string"
  }
 }
}
---
{
 "app_name": "amazon",
 "api_name": "subscribe_prime",
 "path": "/amazon/prime/subscriptions",
 "method": "POST",
 "description": "Subscribe to prime membership.",
 "parameters": [
  {
   "name": "payment_card_id",
   "type": "integer",
   "required": true,
   "description": "ID of the payment card to use for buy prime subscription.",
   "default": null,
   "constraints": []
  },
  {
   "name": "duration",
   "type": "string",
   "required": true,
   "description": "Duration of the prime subscription.",
   "default": null,
   "constraints": [
    "value in ['monthly', 'yearly']"
   ]
  },
  {
   "name": "access_token",
   "type": "string",
   "required": true,
   "description": "Access token obtained from amazon app login.",
   "default": null,
   "constraints": []
  }
 ],
 "response_schemas": {
  "success": {
   "message": "string",
   "prime_subscription_id": 1
  },
  "failure": {
   "message": "string"
  }
 }
}
